-- LeenTrack database installer (generated by bin/build-install-sql.php; do not edit).
-- Import into an EMPTY database in phpMyAdmin (Import tab). If imported twice MySQL stops at the first INSERT with 'Duplicate entry 0001': nothing is changed.
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS schema_migrations (
  version VARCHAR(20) NOT NULL PRIMARY KEY,
  name VARCHAR(190) NOT NULL,
  checksum CHAR(64) NOT NULL,
  batch INT NOT NULL,
  applied_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

-- ---------------------------------------------------------------- 0001 rate_limits
CREATE TABLE IF NOT EXISTS rate_limits (
  key_hash     CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  window_start INT UNSIGNED NOT NULL,
  hits         INT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (key_hash, window_start),
  KEY idx_rate_limits_window (window_start)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
INSERT INTO schema_migrations (version, name, checksum, batch) VALUES ('0001', 'rate_limits', 'cea91ea23ba8d20a38a6628fe1b09a85ae5e74f816c62ae1f0b2afa2dea7a4f0', 1);

-- ---------------------------------------------------------------- 0002 identity
-- Identity. User ids are CHAR(36) UUIDs so Supabase auth.users ids can be preserved on import.
CREATE TABLE users (
  id                  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  email               VARCHAR(254) NOT NULL,
  password_hash       VARCHAR(255) NULL,
  legacy_bcrypt_hash  VARCHAR(100) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'imported GoTrue bcrypt; verified once then NULLed',
  email_verified_at   DATETIME(3) NULL,
  phone               VARCHAR(32) NULL,
  phone_verified_at   DATETIME(3) NULL,
  status              ENUM('active','disabled','pending_deletion') NOT NULL DEFAULT 'active',
  last_login_at       DATETIME(3) NULL,
  created_at          DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at          DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  deleted_at          DATETIME(3) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_users_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE user_profiles (
  user_id        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  full_name      VARCHAR(150) NULL,
  address        VARCHAR(300) NULL,
  currency       CHAR(3) NOT NULL DEFAULT 'NGN',
  avatar_path    VARCHAR(255) NULL,
  notification_prefs JSON NULL,
  created_at     DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at     DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (user_id),
  CONSTRAINT fk_profiles_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- One row per login (device). Only SHA-256 hashes of tokens are stored.
CREATE TABLE auth_sessions (
  id                 CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id            CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  device_id          VARCHAR(64) NULL,
  device_name        VARCHAR(120) NULL,
  platform           VARCHAR(32) NULL,
  access_hash        CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  access_expires_at  DATETIME(3) NOT NULL,
  refresh_hash       CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  prev_refresh_hash  CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'previous refresh token: presenting it again = theft signal',
  refresh_expires_at DATETIME(3) NOT NULL,
  ip                 VARCHAR(45) NULL,
  user_agent         VARCHAR(255) NULL,
  created_at         DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  last_used_at       DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  revoked_at         DATETIME(3) NULL,
  revoked_reason     VARCHAR(40) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_sessions_access (access_hash),
  UNIQUE KEY uq_sessions_refresh (refresh_hash),
  KEY idx_sessions_prev_refresh (prev_refresh_hash),
  KEY idx_sessions_user (user_id, revoked_at),
  CONSTRAINT fk_sessions_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

-- Single-use tokens e-mailed to users (verify e-mail, reset password).
CREATE TABLE user_tokens (
  id          BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  user_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  purpose     ENUM('verify_email','reset_password') NOT NULL,
  token_hash  CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  expires_at  DATETIME(3) NOT NULL,
  used_at     DATETIME(3) NULL,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_user_tokens_hash (token_hash),
  KEY idx_user_tokens_user (user_id, purpose, used_at),
  CONSTRAINT fk_user_tokens_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

-- Platform administrators. NEVER derived from a profile/role field or request data.
-- Rows are created only by bin/make-admin.php (CLI) or by an existing admin with step-up (later phase).
CREATE TABLE platform_admins (
  user_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  created_by  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (user_id),
  CONSTRAINT fk_admin_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
INSERT INTO schema_migrations (version, name, checksum, batch) VALUES ('0002', 'identity', '8dc63ac86c99af689aa313d44a25d48c9fdbf77cc5e5dbddf7521bd1dc2433c5', 1);

-- ---------------------------------------------------------------- 0003 tenancy
CREATE TABLE businesses (
  id                         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name                       VARCHAR(150) NOT NULL,
  business_type              VARCHAR(60) NULL,
  currency                   CHAR(3) NOT NULL DEFAULT 'NGN',
  tax_rate                   DECIMAL(5,2) NOT NULL DEFAULT 0.00,
  owner_user_id              CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  -- Billing columns: written ONLY by the billing service / platform admin, never by tenant endpoints.
  plan                       ENUM('free','growth','business') NOT NULL DEFAULT 'free',
  plan_status                ENUM('active','cancelled','suspended','expired') NOT NULL DEFAULT 'active',
  plan_expiry                DATETIME(3) NULL,
  paystack_customer_id       VARCHAR(80) NULL,
  paystack_subscription_code VARCHAR(80) NULL,
  created_at                 DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at                 DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  deleted_at                 DATETIME(3) NULL,
  PRIMARY KEY (id),
  KEY idx_businesses_owner (owner_user_id),
  KEY idx_businesses_plan_expiry (plan, plan_expiry),
  CONSTRAINT fk_businesses_owner FOREIGN KEY (owner_user_id) REFERENCES users(id) ON DELETE RESTRICT,
  CONSTRAINT chk_businesses_tax CHECK (tax_rate >= 0 AND tax_rate <= 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE locations (
  id             CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name           VARCHAR(150) NOT NULL,
  location_type  ENUM('store','warehouse','kiosk','office') NOT NULL DEFAULT 'store',
  address        VARCHAR(300) NULL,
  city           VARCHAR(100) NULL,
  state          VARCHAR(100) NULL,
  postal_code    VARCHAR(20) NULL,
  country        VARCHAR(100) NULL DEFAULT 'Nigeria',
  phone          VARCHAR(40) NULL,
  email          VARCHAR(150) NULL,
  manager_name   VARCHAR(150) NULL,
  is_active      TINYINT(1) NOT NULL DEFAULT 1,
  is_default     TINYINT(1) NOT NULL DEFAULT 0,
  timezone       VARCHAR(64) NOT NULL DEFAULT 'Africa/Lagos',
  business_hours JSON NULL,
  created_at     DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at     DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_locations_business (business_id, is_active),
  CONSTRAINT fk_locations_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Membership = the ONLY source of a user's role in a business. user_id is NULL until an invite is accepted.
-- Access requires status='active' AND user_id = caller: an invited e-mail address alone grants nothing.
CREATE TABLE business_members (
  id                CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_id       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  user_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  email             VARCHAR(254) NOT NULL,
  name              VARCHAR(150) NULL,
  role              ENUM('owner','manager','cashier') NOT NULL,
  status            ENUM('invited','active','inactive') NOT NULL,
  invited_by        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  invite_token_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,
  invite_expires_at DATETIME(3) NULL,
  joined_at         DATETIME(3) NULL,
  created_at        DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at        DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_member_user (business_id, user_id),
  UNIQUE KEY uq_member_email (business_id, email),
  UNIQUE KEY uq_member_invite (invite_token_hash),
  KEY idx_member_user (user_id, status),
  CONSTRAINT fk_member_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE RESTRICT,
  CONSTRAINT fk_member_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Optional outlet restriction. No rows for a member = access to all outlets of the business.
CREATE TABLE member_outlets (
  member_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  location_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  PRIMARY KEY (member_id, location_id),
  CONSTRAINT fk_mo_member FOREIGN KEY (member_id) REFERENCES business_members(id) ON DELETE CASCADE,
  CONSTRAINT fk_mo_location FOREIGN KEY (location_id) REFERENCES locations(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE audit_logs (
  id             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  business_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  actor_user_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  action         VARCHAR(80) NOT NULL,
  entity_type    VARCHAR(60) NULL,
  entity_id      VARCHAR(64) NULL,
  before_json    JSON NULL,
  after_json     JSON NULL,
  ip             VARCHAR(45) NULL,
  user_agent     VARCHAR(255) NULL,
  request_id     CHAR(36) NULL,
  created_at     DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_audit_business (business_id, created_at),
  KEY idx_audit_actor (actor_user_id, created_at),
  KEY idx_audit_action (action, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
INSERT INTO schema_migrations (version, name, checksum, batch) VALUES ('0003', 'tenancy', 'be8186aabef7d0dc7d9a6d69dc89fcb698c86e02eaacbcffb9ae287220009a0c', 1);

-- ---------------------------------------------------------------- 0004 catalogue_stock
CREATE TABLE categories (
  id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name         VARCHAR(100) NOT NULL,
  description  VARCHAR(300) NULL,
  created_at   DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at   DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_categories_name (business_id, name),          -- utf8mb4_0900_ai_ci => case/accent-insensitive uniqueness
  CONSTRAINT fk_categories_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE products (
  id              CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  category_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  name            VARCHAR(200) NOT NULL,
  description     VARCHAR(1000) NULL,
  sku             VARCHAR(80) NULL,
  barcode         VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NULL,
  item_type       ENUM('product','service') NOT NULL DEFAULT 'product',
  selling_price   DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  cost_price      DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  -- Business-wide total = SUM(stock_levels.quantity). Never written directly by clients; only StockService changes it.
  stock_quantity  INT NOT NULL DEFAULT 0,
  min_stock_level INT NOT NULL DEFAULT 0,
  reorder_level   INT NOT NULL DEFAULT 5,
  image_url       VARCHAR(500) NULL,
  is_active       TINYINT(1) NOT NULL DEFAULT 1,
  archived_at     DATETIME(3) NULL,
  created_at      DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at      DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  -- Barcode must be unique among NON-archived products of a business; archiving frees it for reuse.
  barcode_live    VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin GENERATED ALWAYS AS (IF(archived_at IS NULL, barcode, NULL)) VIRTUAL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_products_barcode_live (business_id, barcode_live),
  KEY idx_products_business_active (business_id, archived_at, is_active),
  KEY idx_products_category (business_id, category_id),
  KEY idx_products_sku (business_id, sku),
  KEY idx_products_name (business_id, name),
  CONSTRAINT fk_products_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE RESTRICT,
  CONSTRAINT fk_products_category FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE SET NULL,
  CONSTRAINT chk_products_prices CHECK (selling_price >= 0 AND cost_price >= 0),
  CONSTRAINT chk_products_levels CHECK (min_stock_level >= 0 AND reorder_level >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- Per-outlet stock. Quantity may only go negative through the offline-sync "oversold" path (Phase 4); online code refuses it.
CREATE TABLE stock_levels (
  product_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  location_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  quantity     INT NOT NULL DEFAULT 0,
  updated_at   DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (product_id, location_id),
  KEY idx_levels_business_location (business_id, location_id),
  CONSTRAINT fk_levels_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT,
  CONSTRAINT fk_levels_location FOREIGN KEY (location_id) REFERENCES locations(id) ON DELETE RESTRICT,
  CONSTRAINT fk_levels_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

-- Append-only ledger of every stock change (who, why, how much, resulting quantity).
CREATE TABLE stock_movements (
  id              BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  business_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  product_id      CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  location_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  delta           INT NOT NULL,
  quantity_after  INT NOT NULL,
  reason          VARCHAR(30) NOT NULL,
  ref_type        VARCHAR(30) NULL,
  ref_id          VARCHAR(64) NULL,
  note            VARCHAR(300) NULL,
  actor_user_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at      DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_movements_product (business_id, product_id, created_at),
  KEY idx_movements_location (business_id, location_id, created_at),
  KEY idx_movements_ref (ref_type, ref_id),
  CONSTRAINT fk_movements_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT,
  CONSTRAINT fk_movements_location FOREIGN KEY (location_id) REFERENCES locations(id) ON DELETE RESTRICT,
  CONSTRAINT fk_movements_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE RESTRICT,
  CONSTRAINT chk_movements_nonzero CHECK (delta <> 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
INSERT INTO schema_migrations (version, name, checksum, batch) VALUES ('0004', 'catalogue_stock', 'c64072d53bb495ee0f8fdd7c31ea93a2fa9cd0d00f0bb5c7cac9c0abcea67378', 1);

-- ---------------------------------------------------------------- 0005 customers_loyalty
CREATE TABLE customer_groups (
  id                   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name                 VARCHAR(100) NOT NULL,
  description          VARCHAR(300) NULL,
  discount_percentage  DECIMAL(5,2) NOT NULL DEFAULT 0.00,
  created_at           DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at           DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_groups_business (business_id, name),
  CONSTRAINT fk_groups_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE RESTRICT,
  CONSTRAINT chk_groups_discount CHECK (discount_percentage >= 0 AND discount_percentage <= 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- The production column is customer_group_id (the web app says so explicitly); the API calls it group_id.
-- loyalty_points / total_spent / visit_count / last_visit are written ONLY by the sale and loyalty services.
CREATE TABLE customers (
  id                 CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_id        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  customer_group_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  name               VARCHAR(150) NOT NULL,
  email              VARCHAR(254) NULL,
  phone              VARCHAR(32) NULL,
  address            VARCHAR(300) NULL,
  date_of_birth      DATE NULL,
  notes              VARCHAR(1000) NULL,
  loyalty_points     INT NOT NULL DEFAULT 0,
  total_spent        DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  visit_count        INT NOT NULL DEFAULT 0,
  last_visit         DATETIME(3) NULL,
  archived_at        DATETIME(3) NULL,
  created_at         DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at         DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_customers_business (business_id, archived_at, name),
  KEY idx_customers_phone (business_id, phone),
  KEY idx_customers_email (business_id, email),
  KEY idx_customers_group (business_id, customer_group_id),
  CONSTRAINT fk_customers_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE RESTRICT,
  CONSTRAINT fk_customers_group FOREIGN KEY (customer_group_id) REFERENCES customer_groups(id) ON DELETE SET NULL,
  CONSTRAINT chk_customers_counters CHECK (loyalty_points >= 0 AND total_spent >= 0 AND visit_count >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- No row = defaults (enabled, 1 point per 10,000 spent, 1 point worth 100), exactly like the source.
CREATE TABLE loyalty_settings (
  business_id      CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  enabled          TINYINT(1) NOT NULL DEFAULT 1,
  spend_per_point  DECIMAL(15,2) NOT NULL DEFAULT 10000.00,
  point_value      DECIMAL(15,2) NOT NULL DEFAULT 100.00,
  updated_by       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  updated_at       DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (business_id),
  CONSTRAINT fk_loyalty_settings_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE RESTRICT,
  CONSTRAINT chk_loyalty_rate CHECK (spend_per_point >= 1 AND spend_per_point <= 100000000),
  CONSTRAINT chk_loyalty_value CHECK (point_value >= 0 AND point_value <= 1000000 AND point_value <= spend_per_point)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

-- Append-only. progress_after = money received that has not yet added up to a whole point.
CREATE TABLE loyalty_ledger (
  id               BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  business_id      CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  customer_id      CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  sale_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  kind             ENUM('earn','redeem') NOT NULL,
  money            DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  points           INT NOT NULL,
  progress_after   DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  balance_after    INT NOT NULL,
  spend_per_point  DECIMAL(15,2) NULL,
  point_value      DECIMAL(15,2) NULL,
  note             VARCHAR(200) NULL,
  created_by       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at       DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_ledger_customer (customer_id, id),
  KEY idx_ledger_business (business_id, created_at),
  KEY idx_ledger_sale (sale_id),
  CONSTRAINT fk_ledger_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE RESTRICT,
  CONSTRAINT fk_ledger_customer FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
INSERT INTO schema_migrations (version, name, checksum, batch) VALUES ('0005', 'customers_loyalty', '5c1237de127e9d879cc6d30d8fdc2aa95fa367467399ecf00daa63806bf24760', 1);

-- ---------------------------------------------------------------- 0006 sales
-- Per-business gap-free-on-commit counters (receipt numbers). Allocated LAST in the sale transaction to keep the lock short.
CREATE TABLE document_sequences (
  business_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  kind         VARCHAR(20) CHARACTER SET ascii NOT NULL,
  next_value   BIGINT UNSIGNED NOT NULL DEFAULT 1,
  PRIMARY KEY (business_id, kind),
  CONSTRAINT fk_seq_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE sales (
  id                  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  outlet_id           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'NULL only for imported legacy sales',
  user_id             CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL COMMENT 'cashier',
  customer_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  receipt_number      VARCHAR(60) NOT NULL,
  subtotal            DECIMAL(15,2) NOT NULL,
  discount_amount     DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  group_discount      DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  manual_discount     DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  points_discount     DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  points_redeemed     INT NOT NULL DEFAULT 0,
  tax_rate            DECIMAL(5,2) NOT NULL DEFAULT 0.00 COMMENT 'rate in force when the sale was made',
  tax_amount          DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  total_amount        DECIMAL(15,2) NOT NULL,
  amount_paid         DECIMAL(15,2) NOT NULL DEFAULT 0.00 COMMENT 'money received at the till (capped at total)',
  change_amount       DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  payment_method      ENUM('cash','card','bank_transfer','mobile_money','other') NOT NULL DEFAULT 'cash',
  payment_method_raw  VARCHAR(40) NULL COMMENT 'verbatim legacy value kept by the importer',
  payment_status      ENUM('completed','pending','voided','refunded') NOT NULL DEFAULT 'completed',
  is_credit           TINYINT(1) NOT NULL DEFAULT 0 COMMENT 'sold on credit (even if later fully repaid)',
  notes               VARCHAR(500) NULL,
  client_operation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  request_hash        CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL,
  client_created_at   DATETIME(3) NULL,
  voided_at           DATETIME(3) NULL,
  voided_by           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  void_reason         VARCHAR(200) NULL,
  created_at          DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at          DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_sales_receipt (business_id, receipt_number),
  UNIQUE KEY uq_sales_operation (business_id, client_operation_id),
  KEY idx_sales_business_date (business_id, created_at),
  KEY idx_sales_status_date (business_id, payment_status, created_at),
  KEY idx_sales_customer (business_id, customer_id, created_at),
  KEY idx_sales_outlet (business_id, outlet_id, created_at),
  CONSTRAINT fk_sales_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE RESTRICT,
  CONSTRAINT fk_sales_outlet FOREIGN KEY (outlet_id) REFERENCES locations(id) ON DELETE RESTRICT,
  CONSTRAINT fk_sales_customer FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE RESTRICT,
  CONSTRAINT fk_sales_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT chk_sales_money CHECK (subtotal >= 0 AND discount_amount >= 0 AND tax_amount >= 0 AND total_amount >= 0 AND amount_paid >= 0 AND change_amount >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

-- product_name / item_type are SNAPSHOTS: a receipt keeps showing what was sold even if the product is renamed or archived.
CREATE TABLE sale_items (
  id            CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  sale_id       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  product_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  product_name  VARCHAR(200) NOT NULL,
  item_type     ENUM('product','service') NOT NULL DEFAULT 'product',
  quantity      INT NOT NULL,
  unit_price    DECIMAL(15,2) NOT NULL,
  total_price   DECIMAL(15,2) NOT NULL,
  unit_cost     DECIMAL(15,2) NULL COMMENT 'cost remembered at the moment of sale (profit uses it)',
  position      INT NOT NULL DEFAULT 0,
  created_at    DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_items_sale (sale_id, position),
  KEY idx_items_product (business_id, product_id),
  CONSTRAINT fk_items_sale FOREIGN KEY (sale_id) REFERENCES sales(id) ON DELETE RESTRICT,
  CONSTRAINT fk_items_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT,
  CONSTRAINT chk_items CHECK (quantity > 0 AND unit_price >= 0 AND total_price >= 0 AND (unit_cost IS NULL OR unit_cost >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

-- Payments made AFTER a credit sale. Append-only: corrections are new rows, never edits (endpoints arrive in 3d).
CREATE TABLE debt_repayments (
  id              CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  sale_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  customer_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  amount          DECIMAL(15,2) NOT NULL,
  payment_method  ENUM('cash','card','bank_transfer','mobile_money','other') NOT NULL DEFAULT 'cash',
  notes           VARCHAR(300) NULL,
  client_operation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_by      CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at      DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_repay_operation (business_id, client_operation_id),
  KEY idx_repay_sale (sale_id),
  KEY idx_repay_customer (business_id, customer_id),
  CONSTRAINT fk_repay_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE RESTRICT,
  CONSTRAINT fk_repay_sale FOREIGN KEY (sale_id) REFERENCES sales(id) ON DELETE RESTRICT,
  CONSTRAINT fk_repay_customer FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE RESTRICT,
  CONSTRAINT chk_repay_amount CHECK (amount > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

-- History of edits (written only by SaleService::edit; never updated).
CREATE TABLE sale_edits (
  id              CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  sale_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  edited_by       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  edited_at       DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  reason          VARCHAR(200) NULL,
  old_total       DECIMAL(15,2) NOT NULL,
  new_total       DECIMAL(15,2) NOT NULL,
  paid_so_far     DECIMAL(15,2) NOT NULL,
  balance_due     DECIMAL(15,2) NOT NULL,
  refund_due      DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  extra_paid      DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  extra_method    VARCHAR(20) NULL,
  before_discount DECIMAL(15,2) NULL,
  after_discount  DECIMAL(15,2) NULL,
  before_items    JSON NOT NULL,
  after_items     JSON NOT NULL,
  PRIMARY KEY (id),
  KEY idx_edits_sale (sale_id, edited_at),
  KEY idx_edits_business (business_id, edited_at),
  CONSTRAINT fk_edits_sale FOREIGN KEY (sale_id) REFERENCES sales(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

ALTER TABLE loyalty_ledger ADD CONSTRAINT fk_ledger_sale FOREIGN KEY (sale_id) REFERENCES sales(id) ON DELETE RESTRICT;
