-- ---------------------------------------------------------------- 0009 purchases
-- Suppliers are archived, never deleted: past orders keep pointing at them (the source set supplier_id to NULL on delete).
CREATE TABLE suppliers (
  id            CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  name          VARCHAR(150) NOT NULL,
  contact_name  VARCHAR(150) NULL,
  phone         VARCHAR(40) NULL,
  email         VARCHAR(190) NULL,
  address       VARCHAR(300) NULL,
  notes         VARCHAR(1000) NULL,
  archived_at   DATETIME(3) NULL,
  created_at    DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at    DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_suppliers_business (business_id, archived_at, name),
  CONSTRAINT fk_suppliers_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- status: draft -> ordered -> partially_received -> received ; closed = stopped waiting for the rest; cancelled = nothing was received.
-- outlet_id is where received stock lands (and who may see the order).
CREATE TABLE purchase_orders (
  id            CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  supplier_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  outlet_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  order_number  VARCHAR(30) CHARACTER SET ascii NOT NULL,
  status        ENUM('draft','ordered','partially_received','received','closed','cancelled') NOT NULL DEFAULT 'draft',
  total_cost    DECIMAL(15,2) NOT NULL DEFAULT 0,
  notes         VARCHAR(1000) NULL,
  ordered_at    DATETIME(3) NULL,
  received_at   DATETIME(3) NULL,
  created_by    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at    DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at    DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_po_number (business_id, order_number),
  KEY idx_po_status (business_id, status, outlet_id),
  KEY idx_po_supplier (business_id, supplier_id),
  CONSTRAINT fk_po_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE RESTRICT,
  CONSTRAINT fk_po_supplier FOREIGN KEY (supplier_id) REFERENCES suppliers(id) ON DELETE RESTRICT,
  CONSTRAINT fk_po_outlet FOREIGN KEY (outlet_id) REFERENCES locations(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE purchase_order_items (
  id                 CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  purchase_order_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_id        CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  product_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  product_name       VARCHAR(200) NOT NULL,
  quantity_ordered   INT NOT NULL,
  quantity_received  INT NOT NULL DEFAULT 0,
  unit_cost          DECIMAL(15,2) NOT NULL DEFAULT 0,
  line_total         DECIMAL(15,2) NOT NULL DEFAULT 0,
  position           INT NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  KEY idx_poi_order (purchase_order_id, position),
  KEY idx_poi_product (business_id, product_id),
  CONSTRAINT fk_poi_order FOREIGN KEY (purchase_order_id) REFERENCES purchase_orders(id) ON DELETE RESTRICT,
  CONSTRAINT fk_poi_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT,
  CONSTRAINT chk_poi_qty CHECK (quantity_ordered > 0 AND quantity_received >= 0 AND quantity_received <= quantity_ordered)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- One row per accepted delivery. UNIQUE(business_id, client_operation_id) makes a retried delivery a no-op.
CREATE TABLE purchase_receipts (
  id                   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  purchase_order_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  client_operation_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  request_hash         CHAR(64) CHARACTER SET ascii NOT NULL,
  user_id              CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at           DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_receipt_operation (business_id, client_operation_id),
  KEY idx_receipt_order (purchase_order_id, created_at),
  CONSTRAINT fk_receipt_order FOREIGN KEY (purchase_order_id) REFERENCES purchase_orders(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE purchase_receipt_items (
  receipt_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  item_id     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  quantity    INT NOT NULL,
  PRIMARY KEY (receipt_id, item_id),
  CONSTRAINT fk_ri_receipt FOREIGN KEY (receipt_id) REFERENCES purchase_receipts(id) ON DELETE RESTRICT,
  CONSTRAINT fk_ri_item FOREIGN KEY (item_id) REFERENCES purchase_order_items(id) ON DELETE RESTRICT,
  CONSTRAINT chk_ri_qty CHECK (quantity > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
INSERT INTO schema_migrations (version, name, checksum, batch) VALUES ('0009', 'purchases', 'ff1b3364cfe97e77cd9f1384b08cfe1eadb9155a9d018201e918bd14754e4749', 1);

-- ---------------------------------------------------------------- 0010 transfers
-- pending -> in_transit (source debited) -> completed (destination credited by what arrived) ; cancelled (stock returned if it had shipped).
-- Stock is conserved: shipped = received + variance. A variance is never dropped; it stays on the item row and in the audit log.
CREATE TABLE transfers (
  id                     CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_id            CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  transfer_number        VARCHAR(30) CHARACTER SET ascii NOT NULL,
  from_location_id       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  to_location_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  status                 ENUM('pending','in_transit','completed','cancelled') NOT NULL DEFAULT 'pending',
  notes                  VARCHAR(1000) NULL,
  created_by             CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  shipped_at             DATETIME(3) NULL,
  received_at            DATETIME(3) NULL,
  cancelled_at           DATETIME(3) NULL,
  dispatch_operation_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  dispatch_hash          CHAR(64) CHARACTER SET ascii NULL,
  receive_operation_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  receive_hash           CHAR(64) CHARACTER SET ascii NULL,
  created_at             DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at             DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_transfer_number (business_id, transfer_number),
  UNIQUE KEY uq_transfer_dispatch_op (business_id, dispatch_operation_id),
  UNIQUE KEY uq_transfer_receive_op (business_id, receive_operation_id),
  KEY idx_transfer_status (business_id, status),
  CONSTRAINT fk_transfer_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE RESTRICT,
  CONSTRAINT fk_transfer_from FOREIGN KEY (from_location_id) REFERENCES locations(id) ON DELETE RESTRICT,
  CONSTRAINT fk_transfer_to FOREIGN KEY (to_location_id) REFERENCES locations(id) ON DELETE RESTRICT,
  CONSTRAINT chk_transfer_distinct CHECK (from_location_id <> to_location_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE transfer_items (
  id                  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  transfer_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_id         CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  product_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  product_name        VARCHAR(200) NOT NULL,
  quantity_requested  INT NOT NULL,
  quantity_shipped    INT NULL,
  quantity_received   INT NULL,
  position            INT NOT NULL DEFAULT 0,
  PRIMARY KEY (id),
  UNIQUE KEY uq_transfer_product (transfer_id, product_id),
  KEY idx_ti_product (business_id, product_id),
  CONSTRAINT fk_ti_transfer FOREIGN KEY (transfer_id) REFERENCES transfers(id) ON DELETE RESTRICT,
  CONSTRAINT fk_ti_product FOREIGN KEY (product_id) REFERENCES products(id) ON DELETE RESTRICT,
  CONSTRAINT chk_ti_qty CHECK (quantity_requested > 0 AND (quantity_shipped IS NULL OR (quantity_shipped >= 0 AND quantity_shipped <= quantity_requested))
    AND (quantity_received IS NULL OR (quantity_received >= 0 AND quantity_received <= COALESCE(quantity_shipped, 0))))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
INSERT INTO schema_migrations (version, name, checksum, batch) VALUES ('0010', 'transfers', '9f6b6b0ea31067673df1987ce1072abfa8405bd3e057a80d3998ce6d330534ef', 1);

-- ---------------------------------------------------------------- 0011 account_lifecycle
-- must_change_password: set when a migrated (legacy) account signs in with a password that fails today's policy. Soft: clients prompt, nothing is blocked.
-- deletion_*: 14-day grace between a deletion request and the purge job (sign-in is disabled meanwhile; the user can cancel).
-- anonymised_at: the user row is kept (sales.user_id must stay valid) but every personal field is blanked by the purge job.
ALTER TABLE users
  ADD COLUMN must_change_password   TINYINT(1) NOT NULL DEFAULT 0 AFTER status,
  ADD COLUMN deletion_requested_at  DATETIME(3) NULL AFTER must_change_password,
  ADD COLUMN deletion_scheduled_at  DATETIME(3) NULL AFTER deletion_requested_at,
  ADD COLUMN anonymised_at          DATETIME(3) NULL AFTER deletion_scheduled_at,
  ADD KEY idx_users_deletion (status, deletion_scheduled_at);
INSERT INTO schema_migrations (version, name, checksum, batch) VALUES ('0011', 'account_lifecycle', '76e29ef6e6da7e79aa3493271ea9f36220b681968785bdbf3b4f9a7a38482bd5', 1);

-- ---------------------------------------------------------------- 0012 supplier_payments
-- Money paid to a supplier against goods that have actually been received. A payment can never exceed what is still owed on its order
-- (no prepayments, no negative balances). Payments are immutable: a mistake is corrected by a counter-entry, never by editing history.
-- They are NOT expenses: buying stock is an inventory movement, and its cost reaches profit only when the goods are sold (remembered unit cost).
CREATE TABLE supplier_payments (
  id                   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  supplier_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  purchase_order_id    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  amount               DECIMAL(15,2) NOT NULL,
  payment_method       ENUM('cash','bank_transfer','card','mobile_money','other') NOT NULL DEFAULT 'bank_transfer',
  reference            VARCHAR(100) NULL,
  notes                VARCHAR(300) NULL,
  client_operation_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  request_hash         CHAR(64) CHARACTER SET ascii NOT NULL,
  created_by           CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at           DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_supplier_payment_op (business_id, client_operation_id),
  KEY idx_sp_order (purchase_order_id, created_at),
  KEY idx_sp_supplier (business_id, supplier_id, created_at),
  CONSTRAINT fk_sp_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE RESTRICT,
  CONSTRAINT fk_sp_supplier FOREIGN KEY (supplier_id) REFERENCES suppliers(id) ON DELETE RESTRICT,
  CONSTRAINT fk_sp_order FOREIGN KEY (purchase_order_id) REFERENCES purchase_orders(id) ON DELETE RESTRICT,
  CONSTRAINT chk_sp_amount CHECK (amount > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
INSERT INTO schema_migrations (version, name, checksum, batch) VALUES ('0012', 'supplier_payments', '64ac08475b9bdda0e748c61e5090ae83d67e9318396d34a53d1ca8790ea3812a', 1);

-- ---------------------------------------------------------------- 0013 billing
-- Subscription payments. A row is created by the SERVER before the customer is sent to the payment provider; the amount, plan and cycle are
-- fixed here and are the only thing a provider confirmation is compared with (the source trusted client/webhook metadata: audit S-04).
-- Rows are RETAINED, pseudonymised, when a business is deleted (tax/accounting): business_id is set to NULL by the foreign key and user_id is
-- blanked by the purge job. Nothing else about the customer is stored here.
CREATE TABLE payments (
  id                       CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  business_id              CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  user_id                  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  provider                 ENUM('paystack') NOT NULL DEFAULT 'paystack',
  reference                VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  plan                     ENUM('growth','business') NOT NULL,
  cycle                    ENUM('monthly','quarterly','yearly') NOT NULL,
  currency                 CHAR(3) NOT NULL,
  amount_minor             BIGINT UNSIGNED NOT NULL,
  status                   ENUM('pending','success','failed','abandoned','refunded') NOT NULL DEFAULT 'pending',
  provider_transaction_id  VARCHAR(64) NULL,
  failure_reason           VARCHAR(100) NULL,
  period_start             DATETIME(3) NULL,
  period_end               DATETIME(3) NULL,
  paid_at                  DATETIME(3) NULL,
  settled_via              ENUM('verify','webhook') NULL,
  created_at               DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at               DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_payment_reference (provider, reference),
  KEY idx_payments_business (business_id, created_at),
  KEY idx_payments_retention (business_id, created_at),
  CONSTRAINT fk_payments_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE SET NULL,
  CONSTRAINT chk_payments_amount CHECK (amount_minor > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- One row per distinct webhook delivery (hash of the raw body): a repeated delivery is acknowledged and ignored. The body itself is NOT stored
-- (it contains the customer's e-mail and card hints); only what is needed to explain what happened.
CREATE TABLE webhook_events (
  id             BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  provider       ENUM('paystack') NOT NULL,
  payload_hash   CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  event_type     VARCHAR(60) NOT NULL,
  reference      VARCHAR(64) CHARACTER SET ascii NULL,
  outcome        VARCHAR(40) NOT NULL,
  received_at    DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_webhook_payload (provider, payload_hash),
  KEY idx_webhook_reference (provider, reference)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
INSERT INTO schema_migrations (version, name, checksum, batch) VALUES ('0013', 'billing', 'c508a5373925f3178254495b8fab32603dc4aaa014cae05821a9b0aa642e3d01', 1);

-- ---------------------------------------------------------------- 0014 platform_notices
-- Announcements from the platform operator to every signed-in user (maintenance, pricing changes). The source stored a "broadcast" as an
-- audit-log row that nothing ever displayed; clients read GET /notices and show a banner.
CREATE TABLE platform_notices (
  id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  title       VARCHAR(120) NOT NULL,
  body        VARCHAR(1000) NOT NULL,
  level       ENUM('info','warning','critical') NOT NULL DEFAULT 'info',
  starts_at   DATETIME(3) NOT NULL,
  ends_at     DATETIME(3) NULL,
  created_by  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_notices_active (starts_at, ends_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
INSERT INTO schema_migrations (version, name, checksum, batch) VALUES ('0014', 'platform_notices', '829c19bbba2b96a9d40f1bccedec4f8ae238fca6f02db69ad3d2afb3d920bedd', 1);

-- ---------------------------------------------------------------- 0015 ops
-- Low-stock e-mail alert settings per business (the source kept these as free-form key/value rows in a `settings` table).
CREATE TABLE stock_alert_settings (
  business_id   CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  enabled       TINYINT(1) NOT NULL DEFAULT 0,
  email         VARCHAR(254) NULL,
  frequency     ENUM('daily','hourly') NOT NULL DEFAULT 'daily',
  last_sent_at  DATETIME(3) NULL,
  updated_by    CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  updated_at    DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (business_id),
  KEY idx_alerts_enabled (enabled, last_sent_at),
  CONSTRAINT fk_alerts_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

-- One row per scheduled-job execution (cron). Lets the operator see that the nightly jobs really run, and what they found.
CREATE TABLE job_runs (
  id            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  job           VARCHAR(40) CHARACTER SET ascii NOT NULL,
  status        ENUM('running','ok','failed') NOT NULL DEFAULT 'running',
  started_at    DATETIME(3) NOT NULL,
  finished_at   DATETIME(3) NULL,
  summary       JSON NULL,
  PRIMARY KEY (id),
  KEY idx_job_runs (job, started_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
INSERT INTO schema_migrations (version, name, checksum, batch) VALUES ('0015', 'ops', '9d6b152566f8dc4ba6115a90b8f4b3b6afe498a3be145473838afc845d84f657', 1);

-- ---------------------------------------------------------------- 0016 sync
-- Offline sync ledger: one row per operation a device has pushed (see docs/14_SYNC_PROTOCOL.md).
-- The ledger is a cache of outcomes plus the inbox of operations that need a person; correctness never depends on it, because every
-- operation type is ALSO idempotent in its own table (sales/repayments by client_operation_id, new records by client-chosen id,
-- stock adjustments by movement reference). So a crash between "applied" and "recorded" only means the next retry is answered again.
CREATE TABLE sync_operations (
  id                   BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  business_id          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  client_operation_id  CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  device_id            VARCHAR(64) NULL,
  user_id              CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  type                 VARCHAR(40) CHARACTER SET ascii NOT NULL,
  status               ENUM('applied','conflict','rejected','discarded') NOT NULL,
  code                 VARCHAR(40) CHARACTER SET ascii NULL,
  message              VARCHAR(300) NULL,
  request_hash         CHAR(64) CHARACTER SET ascii NOT NULL,
  payload              JSON NULL COMMENT 'kept only while the operation still needs a person (conflict/rejected)',
  result               JSON NULL,
  client_created_at    DATETIME(3) NULL,
  occurred_at          DATETIME(3) NULL COMMENT 'client time corrected for the device clock error; what the record is dated',
  received_at          DATETIME(3) NOT NULL,
  processed_at         DATETIME(3) NOT NULL,
  resolved_by          CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL,
  resolved_at          DATETIME(3) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_sync_operation (business_id, client_operation_id),
  KEY idx_sync_attention (business_id, status, received_at),
  KEY idx_sync_user (business_id, user_id, status),
  CONSTRAINT fk_sync_business FOREIGN KEY (business_id) REFERENCES businesses(id) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
INSERT INTO schema_migrations (version, name, checksum, batch) VALUES ('0016', 'sync', 'eabceb08811f5ec0a6855f3948f833ae57c66e1aae9bc565a2603ff5caef0816', 1);

